namespace ghidra.file.formats.android.fbpk;




using ghidra.app.util.bin;
using ghidra.formats.gfilesystem;
using ghidra.formats.gfilesystem.annotations;
using ghidra.formats.gfilesystem.factory;
using ghidra.util.exception;
using ghidra.util.exception;
using ghidra.util.task;

/* @FileSystemInfo(
	type = "androidbootloaderfbpk", // ([a-z0-9]+ only)
	description = "Android Boot Loader Image (FBPK)",
	factory = typeof(GFileSystemBaseFactory)
) */

public class FBPK_FileSystem : GFileSystemBase {
	private List<GFileImpl> fileList = new();
	private Map<GFileImpl, FBPK_Partition> map = new();

	public FBPK_FileSystem(string fileSystemName, ByteProvider provider) : base(fileSystemName, provider)
    {
	}

	/* @Override */
	public bool isValid(TaskMonitor monitor)
    {
		byte[] bytes = provider.readBytes(0, FBPK_Constants.FBPK.length());
		return FBPK_Constants.FBPK.equals(new string(bytes).trim());
	}

	/* @Override */
	public void open(TaskMonitor monitor)
    {
		BinaryReader reader = new BinaryReader(provider, true /*might not always be LE*/ );
		FBPK header = FBPK_Factory.getFBPK(reader);
		List<FBPK_Partition> partitions = header.getPartitions();
		foreach (FBPK_Partition partition in partitions) {
			if (partition.isFile()) {
				GFileImpl file = GFileImpl.fromFilename(this, root, partition.getName(), false,
					partition.getDataSize(), null);
				fileList.add(file);
				map.put(file, partition);
			}
		}
	}

	/* @Override */
	public List<GFile> getListing(GFile directory)
    {
		return new(fileList);
	}

	/* @Override */
	public ByteProvider getByteProvider(GFile file, TaskMonitor monitor)
    {

		FBPK_Partition partition = map.get(file);
		if (partition != null) {
			return new ByteProviderWrapper(provider, partition.getDataStartOffset(),
				Integer.toUnsignedLong(partition.getDataSize()), file.getFSRL());
		}
		return null;
	}

}
